const langEl = document.getElementById('language'); const sections = ['home', 'about', 'manufacturing', 'capacity', 'products', 'quality', 'gallery', 'contact']; const safe = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); let selected = 'en'; function render(l) {
  selected = l; const d = translations[l]; document.documentElement.lang = l; document.title = 'VIET HAN | ' + d.nav[0]; document.querySelectorAll('[data-t]').forEach(el => el.textContent = d[el.dataset.t] || ''); document.getElementById('nav').innerHTML = sections.map((s, i) => `<a href="#${s}">${safe(d.nav[i])}</a>`).join(''); document.getElementById('stats').innerHTML = ['10+', '260', '4', '3'].map((n, i) => `<div class="stat"><strong>${n}</strong><span>${safe(d.facts[i])}</span></div>`).join('');
  document.getElementById('stages').innerHTML =
    d.stages.map((stage, i) => {
      const number = String(i + 1).padStart(2, '0');

      return `
      <div class="step" data-step="${number}">
        <b>${number}</b>
        <span>${safe(stage)}</span>
      </div>
    `;
    }).join('');
  document.getElementById('capacityCards').innerHTML = [30000, 50000, 80000].map((n, i) => `<div class="card"><span>${safe(d.capacityNames[i])}</span><strong>${n.toLocaleString('en-US')}</strong><small class="muted">${safe(d.perMonth)}</small></div>`).join(''); document.getElementById('staff').innerHTML = factoryData.employeeBreakdown.map(x => `<div class="stat"><strong>${x[1]}</strong><span>${safe(x[0])}</span></div>`).join(''); document.getElementById('tableheads').innerHTML = [d.machine, d.model, d.qty].map(x => `<th>${safe(x)}</th>`).join(''); document.getElementById('equipment').innerHTML = factoryData.equipment.map(x => `<tr><td>${safe(x.name)}</td><td>${safe(x.model)}</td><td>${x.qty}</td></tr>`).join(''); renderProducts(d); document.getElementById('markets').innerHTML =
    [70, 20, 10].map((n, i) => `
    <div class="card">
      <strong>${n}%</strong>
      <span>${safe(d.market[i])}</span>
    </div>
  `).join('');
  document.getElementById('galleryGrid').innerHTML = Array.from({ length: 9 }, (_, i) => `<img loading="lazy" src="assets/factory-${String(i + 1).padStart(2, '0')}.jpg" alt="Viet Han factory photograph ${i + 1}">`).join(''); renderDepartments(d); d.fields.forEach((x, i) => document.getElementById('field' + i).textContent = x); const select = document.getElementById('productSelect'); const v = select.value; select.innerHTML = d.products.map((x, i) => `<option value="${i}">${safe(x)}</option>`).join(''); if (v && Number(v) < d.products.length) select.value = v; document.getElementById('send').textContent = d.submit; langEl.value = l; try { localStorage.setItem('viviha-lang', l) } catch (e) { }
} langEl.addEventListener('change', e => render(e.target.value)); document.getElementById('rfq').addEventListener('submit', e => { e.preventDefault(); const f = new FormData(e.currentTarget); const d = translations[selected]; const lines = ['Company: ' + f.get('company'), 'Email: ' + f.get('email'), 'Product: ' + translations.en.products[Number(f.get('product'))], 'Estimated quantity: ' + f.get('qty'), 'Requirements: ' + f.get('message')]; location.href = 'mailto:viethannghean@gmail.com?subject=' + encodeURIComponent('Manufacturing inquiry - ' + f.get('company')) + '&body=' + encodeURIComponent(lines.join('\n')); }); let saved = 'en'; try { saved = localStorage.getItem('viviha-lang') || 'en' } catch (e) { }/* Initial render occurs after product carousel is initialized. */


