const slideState = {};
const photoLabels = {
  en: { previous: 'Previous photo', next: 'Next photo', open: 'Enlarge photo', close: 'Close enlarged photo', hint: 'Click photo to enlarge' },
  vi: { previous: 'Ảnh trước', next: 'Ảnh tiếp theo', open: 'Phóng to ảnh', close: 'Đóng ảnh phóng to', hint: 'Nhấn vào ảnh để phóng to' },
  ko: { previous: '이전 사진', next: '다음 사진', open: '사진 확대', close: '확대 보기 닫기', hint: '사진을 클릭하면 확대됩니다' }
};
const photoViewer = document.getElementById('photoViewer');
const viewerImage = document.getElementById('viewerImage');
let viewerCategory = null;
let previousFocus = null;
function renderProducts(d) {
  const grid = document.getElementById('productsGrid');
  const txt = photoLabels[selected];
  grid.innerHTML = d.products.map((title, category) => {
    const files = productImages[category];
    if (!files || !files.length) return `<article class="product">${safe(title)}</article>`;
    const index = (slideState[category] || 0) % files.length;
    return `<article class="product product-with-photos" data-category="${category}">
      <div class="product-photo-wrap">
        <button type="button" class="product-open" data-photo-open="${category}" aria-label="${safe(txt.open)}: ${safe(title)}">
          <img class="product-photo" src="${files[index]}" alt="${safe(title)} — ${index + 1}/${files.length}" loading="lazy">
          <span class="zoom-indicator" aria-hidden="true">⤢</span>
        </button>
        <button type="button" class="photo-arrow photo-prev" data-photo-prev="${category}" aria-label="${safe(txt.previous)}">&#10094;</button>
        <button type="button" class="photo-arrow photo-next" data-photo-next="${category}" aria-label="${safe(txt.next)}">&#10095;</button>
        <span class="photo-count">${index + 1} / ${files.length}</span>
      </div>
      <div class="product-caption"><strong>${safe(title)}</strong><small>${safe(txt.hint)}</small></div>
    </article>`;
  }).join('');
};

/* =====================================
   VIET HAN - DEPARTMENT PHOTO CAROUSEL
   ===================================== */

function getPhotoTitle(category) {
  const d = translations[selected];

  return category < 8
    ? d.products[category]
    : d.depts[category - 8];
}

function renderDepartments(d) {
  const grid = document.getElementById("departments");
  const txt = photoLabels[selected];

  grid.innerHTML = d.depts.map((title, i) => {
    const category = i + 8;
    const files = productImages[category] || [];

    if (!files.length) {
      return `
        <article class="dept">
          <strong>${safe(title)}</strong>
          <small>${safe(d.pending)}</small>
        </article>
      `;
    }

    const index = (slideState[category] || 0) % files.length;
    const hasMultiple = files.length > 1;

    return `
      <article
        class="product product-with-photos"
        data-category="${category}"
      >
        <div class="product-photo-wrap">

          <button
            type="button"
            class="product-open"
            data-photo-open="${category}"
            aria-label="${safe(txt.open)}: ${safe(title)}"
          >
            <img
              class="product-photo"
              src="${safe(files[index])}"
              alt="${safe(title)} - ${index + 1}/${files.length}"
              loading="lazy"
            >

            <span
              class="zoom-indicator"
              aria-hidden="true"
            >⤢</span>
          </button>

          ${hasMultiple ? `
            <button
              type="button"
              class="photo-arrow photo-prev"
              data-photo-prev="${category}"
              aria-label="${safe(txt.previous)}"
            >&#10094;</button>

            <button
              type="button"
              class="photo-arrow photo-next"
              data-photo-next="${category}"
              aria-label="${safe(txt.next)}"
            >&#10095;</button>
          ` : ""}

          <span class="photo-count">
            ${index + 1} / ${files.length}
          </span>

        </div>

        <div class="product-caption">
          <strong>${safe(title)}</strong>
          <small>${safe(txt.hint)}</small>
        </div>
      </article>
    `;
  }).join("");
}


function changePhoto(category, step) {
  if (category === null) return;

  const images = productImages[category];
  if (!images || !images.length) return;

  slideState[category] =
    ((slideState[category] || 0) + step + images.length)
    % images.length;

  if (viewerCategory === category) {
    updateViewer();
  }

  const card = document.querySelector(
    `.product[data-category="${category}"]`
  );

  if (card) {
    const index = slideState[category];
    const img = card.querySelector(".product-photo");
    const count = card.querySelector(".photo-count");

    if (img) {
      img.src = images[index];
      img.alt =
        `${getPhotoTitle(category)} - ${index + 1}/${images.length}`;
    }

    if (count) {
      count.textContent = `${index + 1} / ${images.length}`;
    }
  }
}


function updateViewer() {
  if (viewerCategory === null) return;

  const images = productImages[viewerCategory];

  if (!images || !images.length) return;

  const index = slideState[viewerCategory] || 0;
  const title = getPhotoTitle(viewerCategory);

  viewerImage.src = images[index];
  viewerImage.alt =
    `${title} - ${index + 1}/${images.length}`;

  document.getElementById("viewerTitle").textContent = title;

  document.getElementById("viewerCount").textContent =
    `${index + 1} / ${images.length}`;

  const txt = photoLabels[selected];

  document.getElementById("viewerClose")
    .setAttribute("aria-label", txt.close);

  document.getElementById("viewerPrev")
    .setAttribute("aria-label", txt.previous);

  document.getElementById("viewerNext")
    .setAttribute("aria-label", txt.next);

  const hasMultiple = images.length > 1;

  document.getElementById("viewerPrev").hidden = !hasMultiple;
  document.getElementById("viewerNext").hidden = !hasMultiple;
}

function openViewer(category) {
  previousFocus = document.activeElement;
  viewerCategory = category;
  photoViewer.hidden = false;
  document.body.classList.add('viewer-active');
  updateViewer();
  document.getElementById('viewerClose').focus();
}
function closeViewer() {
  if (viewerCategory === null) return;
  viewerCategory = null;
  photoViewer.hidden = true;
  document.body.classList.remove('viewer-active');
  viewerImage.removeAttribute('src');
  previousFocus?.focus();
}
document.getElementById('productsGrid').addEventListener('click', e => {
  const prev = e.target.closest('[data-photo-prev]');
  const next = e.target.closest('[data-photo-next]');
  const open = e.target.closest('[data-photo-open]');
  if (prev) changePhoto(Number(prev.dataset.photoPrev), -1);
  else if (next) changePhoto(Number(next.dataset.photoNext), 1);
  else if (open) openViewer(Number(open.dataset.photoOpen));
});

/* Department card navigation */

document.getElementById("departments")
  .addEventListener("click", e => {

    const prev = e.target.closest("[data-photo-prev]");
    const next = e.target.closest("[data-photo-next]");
    const open = e.target.closest("[data-photo-open]");

    if (prev) {
      changePhoto(Number(prev.dataset.photoPrev), -1);

    } else if (next) {
      changePhoto(Number(next.dataset.photoNext), 1);

    } else if (open) {
      openViewer(Number(open.dataset.photoOpen));
    }

  });

document.getElementById('viewerPrev').addEventListener('click', () => changePhoto(viewerCategory, -1));
document.getElementById('viewerNext').addEventListener('click', () => changePhoto(viewerCategory, 1));
document.getElementById('viewerClose').addEventListener('click', closeViewer);
photoViewer.addEventListener('click', e => { if (e.target === photoViewer) closeViewer() });
document.addEventListener('keydown', e => {
  if (viewerCategory === null) return;
  if (e.key === 'Escape') closeViewer();
  if (e.key === 'ArrowLeft') changePhoto(viewerCategory, -1);
  if (e.key === 'ArrowRight') changePhoto(viewerCategory, 1);
  if (e.key === 'Tab') {
    const focusable = [document.getElementById('viewerClose'), document.getElementById('viewerPrev'), document.getElementById('viewerNext')];
    const ix = focusable.indexOf(document.activeElement);
    if (e.shiftKey && ix === 0) { e.preventDefault(); focusable[2].focus() }
    else if (!e.shiftKey && ix === 2) { e.preventDefault(); focusable[0].focus() }
  }
});

