function updateBuyersLanguage(lang) {
  const section = document.getElementById("buyers");

  if (!section) return;

  const t = buyersTranslations[lang] ||
    buyersTranslations.en;

  const kicker = section.querySelector(".kicker");
  const title = section.querySelector("h2");
  const description = section.querySelector(".lead");
  const note = section.querySelector(".buyers-note");

  if (kicker) kicker.textContent = t.kicker;
  if (title) title.textContent = t.title;

  if (description) {
    description.textContent = t.description;
  }

  if (note) {
    note.textContent = t.note;
  }
}

